from rest_framework import generics, permissions, renderers, status
from rest_framework.response import Response
from .models import VendorInvoice
from .serializers import VendorInvoiceSerializer

class VendorInvoiceDetailUpdateView(generics.RetrieveUpdateAPIView):
    permission_classes = [permissions.IsAuthenticated]
    serializer_class = VendorInvoiceSerializer
    queryset = VendorInvoice.objects.all()
    renderer_classes = [renderers.JSONRenderer, renderers.BrowsableAPIRenderer]

    def get_queryset(self):
        # Enforce vendor isolation at the queryset level regardless of content-type
        return VendorInvoice.objects.filter(vendor=self.request.user.vendor)

    def update(self, request, *args, **kwargs):
        invoice = self.get_object()
        if invoice.vendor != request.user.vendor:
            return Response({"error": "Forbidden"}, status=status.HTTP_403_FORBIDDEN)
        return super().update(request, *args, **kwargs)
